using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEditor;
using UnityEditor.Compilation;
using UnityEngine;
[InitializeOnLoad]
public static class HolmesSourceSkinBoundary {
 const string K="HOLMES121_RUNNING", Done="HOLMES121_IMPORTED", W="HOLMES121_WORK";
 [Serializable] class Ref { public string guid,file_id; }
 [Serializable] class Group { public string topology; public int[] indices; }
 [Serializable] class Matrix { public float[] values; }
 [Serializable] class Influence {public int bone;public float weight; public int bits;}
 [Serializable] class Point {public Influence[] influences;}
 [Serializable] class Skin {public Ref mesh,renderer,root;public Ref[] bones,bone_parents,materials;public Vector3[] vertices,normals;public Vector2[] uv;public Group[] groups;public Matrix[] bindposes;public Point[] weights;public float[] matrix;public int shapes;public bool cloth; public string[] realization;}
 [Serializable] class Task {public string source_model_guid,model_guid,variant_path,kind;}
 [Serializable] class Manifest {public Task[] reference_rebind_tasks;}
 [Serializable] class Report {public string instruction_id="HOLMES-20261012-01",status="FAIL",error,unity_version,phase,package_sha256,finalizer_sha256;public Skin source,post_import,post_apply,variant;public bool apply,source_bytes_preserved,repeat_apply;public string[] rejection;}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);return i<0?"":a[i+1];}
 static string Work=>SessionState.GetString(W,Arg("-freshWork"));
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static Ref Id(UnityEngine.Object o){if(o==null)return null; if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out string g,out long id))throw new Exception("MissingIdentity");return new Ref{guid=g,file_id=id.ToString(System.Globalization.CultureInfo.InvariantCulture)};}
 static float[] M(Matrix4x4 m){return Enumerable.Range(0,16).Select(i=>m[i]).ToArray();}
 static Skin Capture(GameObject root){var s=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var m=s.sharedMesh;var counts=m.GetBonesPerVertex();var weights=m.GetAllBoneWeights();int k=0;var points=new Point[counts.Length];try{for(int v=0;v<counts.Length;v++){var inf=new Influence[counts[v]];for(int j=0;j<inf.Length;j++){var q=weights[k++];inf[j]=new Influence{bone=q.boneIndex,weight=q.weight,bits=BitConverter.ToInt32(BitConverter.GetBytes(q.weight),0)};}points[v]=new Point{influences=inf};}}finally{counts.Dispose();weights.Dispose();}
 return new Skin{mesh=Id(m),renderer=Id(s),root=Id(s.rootBone),bones=s.bones.Select(Id).ToArray(),bone_parents=s.bones.Select(b=>Id(b.parent)).ToArray(),materials=s.sharedMaterials.Select(Id).ToArray(),vertices=m.vertices,normals=m.normals,uv=m.uv,groups=Enumerable.Range(0,m.subMeshCount).Select(i=>new Group{topology=m.GetTopology(i).ToString(),indices=m.GetIndices(i,true)}).ToArray(),bindposes=m.bindposes.Select(b=>new Matrix{values=M(b)}).ToArray(),weights=points,matrix=M(s.transform.localToWorldMatrix),shapes=m.blendShapeCount,cloth=s.GetComponent<Cloth>()!=null,realization=root.GetComponentsInChildren<Transform>(true).Select(t=>{var marker=t.GetComponents<Component>().FirstOrDefault(c=>c!=null&&c.GetType().Name=="VapbRealizationMarker");return marker==null?"":EditorJsonUtility.ToJson(marker);}).Where(x=>x!="").ToArray()}; }
 static HolmesSourceSkinBoundary(){EditorApplication.update+=Wait;AssetDatabase.importPackageCompleted+=n=>SessionState.SetBool(Done,true);CompilationPipeline.assemblyCompilationFinished+=(a,m)=>{if(m.Any(x=>x.type==CompilerMessageType.Error))SessionState.SetBool("HOLMES121_ERRORS",true);};AssemblyReloadEvents.afterAssemblyReload+=()=>SessionState.SetBool("HOLMES121_RELOAD",true);}
 public static void Run(){SessionState.SetString(W,Arg("-freshWork"));SessionState.SetBool(K,true);if(Arg("-freshPhase")=="source"){Source();return;}SessionState.SetBool(Done,false);SessionState.SetBool("HOLMES121_ERRORS",false);SessionState.SetBool("HOLMES121_RELOAD",false);AssetDatabase.ImportPackage(Arg("-freshPackage"),false);}
 static void Source(){var r=new Report{unity_version=Application.unityVersion,phase="source"};try{AssetDatabase.Refresh();var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HolmesSource/Source.fbx");var mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,"Assets/HolmesSource/SourceMaterial.mat");var imp=(ModelImporter)AssetImporter.GetAtPath("Assets/HolmesSource/Source.fbx");imp.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SourceMaterial"),mat);imp.SaveAndReimport();AssetDatabase.SaveAssets();model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HolmesSource/Source.fbx");r.source=Capture(model);if(r.source.vertices.Length!=4||r.source.bones.Length!=2||r.source.groups.Sum(g=>g.indices.Length)!=6||r.source.materials.Any(x=>x==null)||r.source.shapes!=0||r.source.cloth)throw new Exception("FixtureScope");AssetDatabase.ExportPackage(new[]{"Assets/HolmesSource/Source.fbx","Assets/HolmesSource/SourceMaterial.mat"},Path.Combine(Work,"../Source.unitypackage"),ExportPackageOptions.IncludeDependencies);r.package_sha256=Hash(Path.Combine(Work,"../Source.unitypackage"));r.status="PASS";}catch(Exception e){r.error=e.Message;}Finish(r);}
 static void Wait(){if(!SessionState.GetBool(K,false)||!SessionState.GetBool(Done,false)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!SessionState.GetBool("HOLMES121_RELOAD",false))return;SessionState.SetBool(K,false);var r=new Report{unity_version=Application.unityVersion,phase=Arg("-freshPhase")};try{if(SessionState.GetBool("HOLMES121_ERRORS",false))throw new Exception("CompileErrors");const string path="Assets/VAPBExport/manifest.json";var t=JsonUtility.FromJson<Manifest>(File.ReadAllText(path)).reference_rebind_tasks.Single();if(t.kind!="RESTORE_SOURCE_MODEL_SKIN_VARIANT_V1")throw new Exception("TaskKind");string src=AssetDatabase.GUIDToAssetPath(t.source_model_guid),edit=AssetDatabase.GUIDToAssetPath(t.model_guid);r.source=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(src));r.post_import=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));string[] protectedPaths={src,src+".meta"};var hashes=protectedPaths.Select(Hash).ToArray();var errors=new System.Collections.Generic.List<string>();Application.LogCallback log=(msg,stack,type)=>{if(type==LogType.Error||type==LogType.Exception)errors.Add(msg);};Application.logMessageReceived+=log;var f=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("VapbModelSkinFinalizer")).Single(x=>x!=null);r.finalizer_sha256=Hash("Assets/VAPBExport/Editor/VapbModelSkinFinalizer.cs");r.apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});Application.logMessageReceived-=log;r.rejection=errors.ToArray();r.post_apply=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));r.source_bytes_preserved=hashes.SequenceEqual(protectedPaths.Select(Hash));if(r.apply){r.variant=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path));r.repeat_apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});}r.package_sha256=Hash(Arg("-freshPackage"));r.status="OBSERVED";}catch(Exception e){r.error=e.ToString();}Finish(r);}
 static void Finish(Report r){SessionState.SetBool(K,false);File.WriteAllText(Path.Combine(Work,"native.json"),JsonUtility.ToJson(r,true));EditorApplication.Exit(r.status=="FAIL"?1:0);}
}
